#pragma once

#include "signals/internal_signals_ax45mpv.hpp"
#include "utils/ahb.hpp"
#include "utils/axi.hpp"
#include "utils/cpu_signal_registry.hpp"
#include "utils/duplicator.hpp"
#include "utils/ecc.hpp"
#include "utils/signals.hpp"

#include <axi/pin/axi4_initiator.h>
#include <axi/pin/axi4_target.h>
#include <spdlog/spdlog.h>
#include <systemc>
#include <Vax45mpv_premium.h>

#include <cstddef>

#include <array>

// Decode a Verilated LM SRAM array back to raw little-endian bytes -- the
// shared read loop of get_ilm/get_dlm (data bits only, ECC/parity stripped).
// DataWidth/EccType mirror the setters' #if ladder; `if constexpr` keeps the
// VlWide [0]/[1] indexing uninstantiated on scalar-typed (no-ECC) configs.
// HVM bank backdoor copy (HVM transport F1, ROADMAP_hvm): rows are wide
// Verilated words (VlWide -- pure data bits, no ECC/parity); lane k of a row
// holds bytes 4k..4k+3, little-endian (R2, pinned by the head/tail probes of
// tests/vsim/test_vsim_hvm_load.sh). Write zero-fills past len, so the two
// duals below share the geometry and the byte order cannot drift.
void hvm_bank_write(auto& mem, size_t bank_bytes, const uint8_t* data,
                    size_t len)
{
  constexpr size_t lanes = sizeof(mem[0]) / sizeof(mem[0][0]);
  for (size_t row = 0; row < bank_bytes / (lanes * 4); ++row)
    for (size_t lane = 0; lane < lanes; ++lane) {
      uint32_t w = 0;
      for (size_t j = 0; j < 4; ++j) {
        const size_t idx = row * lanes * 4 + lane * 4 + j;
        if (idx < len)
          w |= static_cast<uint32_t>(data[idx]) << (j * 8);
      }
      mem[row][lane] = w;
    }
}

void hvm_bank_read(auto& mem, size_t bank_bytes, uint8_t* out)
{
  constexpr size_t lanes = sizeof(mem[0]) / sizeof(mem[0][0]);
  for (size_t row = 0; row < bank_bytes / (lanes * 4); ++row)
    for (size_t lane = 0; lane < lanes; ++lane) {
      const uint32_t w = mem[row][lane];
      for (size_t j = 0; j < 4; ++j)
        out[row * lanes * 4 + lane * 4 + j] = static_cast<uint8_t>(w >> (j * 8));
    }
}

template <int DataWidth, int EccType>
std::vector<uint8_t> lm_backdoor_read(auto& mem, size_t bytes)
{
  constexpr size_t word_size = DataWidth == 64 ? 8 : 4;
  using word_t = std::conditional_t<DataWidth == 64, uint64_t, uint32_t>;
  std::vector<uint8_t> out(bytes);
  for (size_t i = 0; i < bytes / word_size; ++i) {
    word_t word;
    if constexpr (EccType == 2 && DataWidth == 64)
      word = static_cast<word_t>(mem[i][0])
             | (static_cast<word_t>(mem[i][1]) << 32);
    else if constexpr (EccType == 2)
      word = static_cast<word_t>(mem[i] & 0xFFFFFFFFull);
    else
      word = static_cast<word_t>(mem[i]);
    for (size_t j = 0; j < word_size; ++j)
      out[i * word_size + j] = static_cast<uint8_t>(word >> (j * 8));
  }
  return out;
}

struct ax45mpv_premium_cpu_cluster_subsystem
    : public Vax45mpv_premium,
      public CpuSignalRegistry<ax45mpv_premium_cpu_cluster_subsystem>
{
  using SC_CURRENT_USER_MODULE = ax45mpv_premium_cpu_cluster_subsystem;

  ax45mpv_premium_cpu_cluster_subsystem(
    const sc_core::sc_module_name& name = "ax45mpv_premium")
      : Vax45mpv_premium{name}
  {}

#define VERILOG_DEFINE(key, value) static constexpr auto key = value;
#include <Vax45mpv_premium_config.h>

  // Limit maximum number of cores to 2 due to performance concerns
  static_assert(
    _NDS_NHART <= 2,
    "This subsystem only supports up to 2 cores. Please reconfigure with _NDS_NHART <= 2");

  static constexpr auto SYSTEM_BUS_TYPE = BusTypes::AXI;

  static constexpr auto dmi_addr_width = 9;
  static constexpr auto dmi_data_width = 32;
  static constexpr auto has_shared_cache = (NDS_L2C_CACHE_SIZE_KB > 0);

  using Vax45mpv_premium::contextp;
  using Vax45mpv_premium::final;
  using Vax45mpv_premium::modelName;
  using Vax45mpv_premium::threads;
  using Vax45mpv_premium::trace;

  using bus_cfg =
    axi::axi4_cfg<NDS_BIU_DATA_WIDTH, NDS_BIU_ADDR_WIDTH, NDS_BIU_ID_WIDTH, 1>;

  using slv_cfg = axi::
    axi4_cfg<NDS_BIU_DATA_WIDTH, NDS_BIU_ADDR_WIDTH, NDS_BIU_ID_WIDTH + 4, 1>;

  axi_signals<bus_cfg> mem{"mem"};
  axi::pin::axi4_target<bus_cfg> mem_bfm{"mem_bfm"};

  axi_signals<bus_cfg> mmio{"mmio"};
  axi::pin::axi4_target<bus_cfg> mmio_bfm{"mmio_bfm"};

